using System;
using Moonpop.Core;
using NUnit.Framework;

namespace Moonpop.Tests
{
    public sealed class CoreTests
    {
        private static RunSession Run(){var s=new RunSession(new RunRules());s.Start();return s;}
        [Test] public void InitialStateIsMenu(){var s=new RunSession(new RunRules());Assert.That(s.State,Is.EqualTo(GameState.Menu));Assert.That(s.Lives,Is.EqualTo(3));}
        [Test] public void StartingRunHasThreeLivesAndFullTank(){var s=Run();Assert.That(s.Lives,Is.EqualTo(3));Assert.That(s.Fuel,Is.EqualTo(100));Assert.That(s.State,Is.EqualTo(GameState.Playing));}
        [Test] public void FuelAndDistanceAdvanceOnlyWhilePlaying(){var s=Run();s.Tick(1);Assert.That(s.Fuel,Is.EqualTo(98.15f).Within(.001));Assert.That(s.Distance,Is.EqualTo(26).Within(.001));}
        [Test] public void PauseFreezesAllGameplayTimers(){var s=Run();s.HitObstacle();s.Pause();float fuel=s.Fuel,grace=s.GraceRemaining;double d=s.Distance;s.Tick(999);Assert.That(s.Fuel,Is.EqualTo(fuel));Assert.That(s.Distance,Is.EqualTo(d));Assert.That(s.GraceRemaining,Is.EqualTo(grace));}
        [Test] public void ResumeContinuesTheSameRun(){var s=Run();s.CollectCoin();s.Pause();s.Resume();s.Tick(1);Assert.That(s.Coins,Is.EqualTo(1));Assert.That(s.Distance,Is.GreaterThan(0));}
        [Test] public void OneCollisionCostsExactlyOneLife(){var s=Run();Assert.That(s.HitObstacle(),Is.True);Assert.That(s.Lives,Is.EqualTo(2));}
        [Test] public void DamageGraceRejectsDuplicateCollision(){var s=Run();s.HitObstacle();Assert.That(s.HitObstacle(),Is.False);s.Tick(1.49f);Assert.That(s.HitObstacle(),Is.False);Assert.That(s.Lives,Is.EqualTo(2));}
        [Test] public void DamageGraceExpires(){var s=Run();s.HitObstacle();s.Tick(1.51f);Assert.That(s.HitObstacle(),Is.True);Assert.That(s.Lives,Is.EqualTo(1));}
        [Test] public void ThirdCollisionEndsRun(){var s=Run();for(int i=0;i<3;i++){s.HitObstacle();s.Tick(2);}Assert.That(s.Lives,Is.EqualTo(0));Assert.That(s.State,Is.EqualTo(GameState.GameOver));Assert.That(s.Reason,Is.EqualTo(EndReason.Collision));}
        [Test] public void EmptyFuelEndsRunWithoutDrivingAfterEmpty(){var s=Run();s.Tick(1000);Assert.That(s.Fuel,Is.EqualTo(0));Assert.That(s.State,Is.EqualTo(GameState.GameOver));Assert.That(s.Reason,Is.EqualTo(EndReason.FuelEmpty));Assert.That(s.Elapsed,Is.EqualTo(100/1.85f).Within(.001));}
        [Test] public void FuelPickupRefillsAndClamps(){var s=Run();s.Tick(20);float before=s.Fuel;s.CollectFuel();Assert.That(s.Fuel,Is.EqualTo(before+30).Within(.001));s.CollectFuel();Assert.That(s.Fuel,Is.EqualTo(100));}
        [Test] public void CoinsIncreaseCountAndScore(){var s=Run();s.CollectCoin();s.CollectCoin();Assert.That(s.Coins,Is.EqualTo(2));Assert.That(s.Score,Is.EqualTo(50));}
        [Test] public void BestScoreSurvivesRestart(){var s=Run();for(int i=0;i<10;i++)s.CollectCoin();s.Start();Assert.That(s.Score,Is.EqualTo(0));Assert.That(s.BestScore,Is.EqualTo(250));}
        [Test] public void RestartResetsFuelLivesTimersCoinsAndReason(){var s=Run();s.HitObstacle();s.CollectCoin();s.Tick(100);s.Start();Assert.That(s.Fuel,Is.EqualTo(100));Assert.That(s.Lives,Is.EqualTo(3));Assert.That(s.Coins,Is.EqualTo(0));Assert.That(s.Elapsed,Is.EqualTo(0));Assert.That(s.Distance,Is.EqualTo(0));Assert.That(s.GraceRemaining,Is.EqualTo(0));Assert.That(s.Reason,Is.EqualTo(EndReason.None));}
        [Test] public void MenuAndGameOverRejectInteractions(){var s=new RunSession(new RunRules());Assert.That(s.CollectCoin(),Is.False);Assert.That(s.HitObstacle(),Is.False);s.Start();s.Tick(100);Assert.That(s.CollectFuel(),Is.False);double d=s.Distance;s.Tick(10);Assert.That(s.Distance,Is.EqualTo(d));}
        [Test] public void MenuPreservesBestScore(){var s=Run();s.CollectCoin();s.ReturnToMenu();Assert.That(s.BestScore,Is.EqualTo(25));Assert.That(s.State,Is.EqualTo(GameState.Menu));}
        [Test] public void DifficultyAndSpeedRiseAndStayBounded(){var s=Run();float previous=s.Speed;for(int i=0;i<10000;i++){if(i%50==0)s.CollectFuel();s.Tick(.1f);Assert.That(s.Speed,Is.GreaterThanOrEqualTo(previous));Assert.That(s.Speed,Is.LessThanOrEqualTo(62));previous=s.Speed;}Assert.That(s.Difficulty,Is.EqualTo(1));}
        [Test] public void InvalidDeltasDoNotCorruptSession(){var s=Run();s.Tick(-1);s.Tick(float.NaN);s.Tick(float.PositiveInfinity);Assert.That(s.Distance,Is.EqualTo(0));Assert.That(s.Fuel,Is.EqualTo(100));}
        [Test] public void InvalidRulesAreRejected(){Assert.Throws<ArgumentException>(()=>new RunSession(new RunRules{LaneChangeSeconds=0}));Assert.Throws<ArgumentException>(()=>new RunSession(new RunRules{MaximumSpeed=float.NaN}));Assert.Throws<ArgumentException>(()=>new RunSession(new RunRules{FuelPerSecond=-1}));}
        [Test] public void LoadedBestScoreCannotBeNegative(){var s=new RunSession(new RunRules(),-42);Assert.That(s.BestScore,Is.EqualTo(0));}
        [Test] public void ScoreDoesNotOverflow(){var s=new RunSession(new RunRules{CoinValue=int.MaxValue});s.Start();s.CollectCoin();s.CollectCoin();Assert.That(s.Score,Is.EqualTo(int.MaxValue));}
        [Test] public void StateEventsFireOnlyOnTransitions(){var s=Run();int count=0;s.StateChanged+=_=>count++;s.Pause();s.Pause();s.Resume();s.ReturnToMenu();s.ReturnToMenu();Assert.That(count,Is.EqualTo(3));}
        [Test] public void PlannerLeavesReachableLaneAndValidMovingMasks(){for(uint seed=1;seed<=30;seed++){var p=new TrafficPlanner(seed);int last=1;for(int i=0;i<3000;i++){var row=p.Next(i/3000f);Assert.That(row.SafeLane,Is.InRange(0,2));Assert.That(row.IsBlocked(row.SafeLane),Is.False);Assert.That(Math.Abs(row.SafeLane-last),Is.LessThanOrEqualTo(1));Assert.That(row.MovingMask&~row.BlockedMask,Is.EqualTo(0));Assert.That(row.CoinCount,Is.InRange(3,5));last=row.SafeLane;}}}
        [Test] public void PlannerHasBothTrafficTypesAndRegularFuel(){var p=new TrafficPlanner(402531387);int moving=0,parked=0,lastFuel=-1;for(int i=0;i<1000;i++){var row=p.Next(.8f);moving|=row.MovingMask;parked|=row.BlockedMask&~row.MovingMask;if(row.HasFuel){if(lastFuel>=0)Assert.That(i-lastFuel,Is.EqualTo(7));lastFuel=i;}}Assert.That(moving,Is.Not.EqualTo(0));Assert.That(parked,Is.Not.EqualTo(0));}
        [Test] public void PlannerIsDeterministicIncludingZeroSeed(){foreach(uint seed in new uint[]{0,42,402531387}){var a=new TrafficPlanner(seed);var b=new TrafficPlanner(seed);for(int i=0;i<1000;i++){var x=a.Next(.5f);var y=b.Next(.5f);Assert.That(x.BlockedMask,Is.EqualTo(y.BlockedMask));Assert.That(x.MovingMask,Is.EqualTo(y.MovingMask));Assert.That(x.SafeLane,Is.EqualTo(y.SafeLane));}}}
        [Test] public void TrafficDensityIncreasesWithDifficulty(){int low=0,high=0;var a=new TrafficPlanner(19);var b=new TrafficPlanner(19);for(int i=0;i<10000;i++){var x=a.Next(0);var y=b.Next(1);for(int lane=0;lane<3;lane++){if(x.IsBlocked(lane))low++;if(y.IsBlocked(lane))high++;}}Assert.That(high,Is.GreaterThan(low*1.5));}
        [Test] public void RowSpacingAllowsLaneChangeEvenWithMovingCars(){for(float v=26;v<=62;v+=.5f){float spacing=TrafficPlanner.RowSpacing(v,0);float maximumDrift=235*3/(v-3);float freeGap=spacing-maximumDrift-7.4f;Assert.That(freeGap/v,Is.GreaterThan(.23f));}}
        [Test] public void SweptCollisionCatchesTunnelling(){Assert.That(SweptCollision.Intersects(0,30,0,-30,1.6f,3.7f),Is.True);}
        [Test] public void SweptCollisionRejectsAdjacentLane(){Assert.That(SweptCollision.Intersects(3.2f,30,3.2f,-30,1.6f,3.7f),Is.False);}
        [Test] public void SweptCollisionHandlesLaneChangesAndStationaryOverlap(){Assert.That(SweptCollision.Intersects(-3.2f,2,0,-2,1.6f,3.7f),Is.True);Assert.That(SweptCollision.Intersects(0,0,0,0,1,1),Is.True);Assert.That(SweptCollision.Intersects(3,3,3,3,1,1),Is.False);}
        [Test] public void SweptCollisionRejectsCrossingAtDifferentTimes(){Assert.That(SweptCollision.Intersects(-5,20,5,5,1,1),Is.False);}
        [Test] public void NitroRequiresAnActiveRun(){var s=new RunSession(new RunRules());s.SetBoostHeld(true);Assert.That(s.Boosting,Is.False);s.Start();s.SetBoostHeld(true);Assert.That(s.Boosting,Is.True);}
        [Test] public void NitroRaisesSpeedAndConsumesEnergyAndExtraFuel(){var s=Run();float baseSpeed=s.Speed;s.SetBoostHeld(true);Assert.That(s.Speed,Is.GreaterThan(baseSpeed));s.Tick(1);Assert.That(s.Nitro,Is.EqualTo(62).Within(.01));Assert.That(s.Fuel,Is.EqualTo(96.85f).Within(.01));Assert.That(s.Distance,Is.EqualTo(26*1.38f).Within(.01));}
        [Test] public void NitroRechargesAndCannotExceedCapacity(){var s=Run();s.SetBoostHeld(true);s.Tick(1);s.SetBoostHeld(false);s.Tick(1);Assert.That(s.Nitro,Is.EqualTo(74).Within(.01));for(int i=0;i<20;i++){s.CollectFuel();s.Tick(1);}Assert.That(s.Nitro,Is.EqualTo(100));}
        [Test] public void ExhaustedNitroNeedsReleaseBeforeRestart(){var s=Run();s.SetBoostHeld(true);s.Tick(3);Assert.That(s.Boosting,Is.False);s.Tick(2);Assert.That(s.Boosting,Is.False);s.SetBoostHeld(false);s.SetBoostHeld(true);Assert.That(s.Boosting,Is.True);}
        [Test] public void LongFrameCannotBoostBeyondItsEnergyBudget(){var s=Run();s.SetBoostHeld(true);s.Tick(5);Assert.That(s.BoostSeconds,Is.EqualTo(100f/38f).Within(.001));Assert.That(s.Boosting,Is.False);Assert.That(s.Fuel,Is.GreaterThan(85));}
        [Test] public void PausingFreezesNitroAndCombo(){var s=Run();s.RegisterNearMiss();s.SetBoostHeld(true);s.Pause();float n=s.Nitro,c=s.ComboRemaining;s.Tick(99);Assert.That(s.Nitro,Is.EqualTo(n));Assert.That(s.ComboRemaining,Is.EqualTo(c));Assert.That(s.Boosting,Is.False);}
        [Test] public void NearMissComboCapsAtFive(){var s=Run();int last=0;for(int i=0;i<7;i++)last=s.RegisterNearMiss();Assert.That(last,Is.EqualTo(500));Assert.That(s.Combo,Is.EqualTo(5));Assert.That(s.BestCombo,Is.EqualTo(5));Assert.That(s.NearMisses,Is.EqualTo(7));}
        [Test] public void ComboExpiresAndStartsAgainAtOne(){var s=Run();s.RegisterNearMiss();s.RegisterNearMiss();s.Tick(3.3f);Assert.That(s.Combo,Is.EqualTo(0));Assert.That(s.RegisterNearMiss(),Is.EqualTo(100));}
        [Test] public void CollisionBreaksComboAndGraceRejectsNearMiss(){var s=Run();s.RegisterNearMiss();s.HitObstacle();Assert.That(s.Combo,Is.EqualTo(0));Assert.That(s.RegisterNearMiss(),Is.EqualTo(0));s.Tick(1.6f);Assert.That(s.RegisterNearMiss(),Is.EqualTo(100));}
        [Test] public void StarStickerRewardIsGrantedOnlyOnce(){var s=Run();for(int i=0;i<20;i++)s.CollectCoin();Assert.That(s.Badges&1,Is.EqualTo(1));Assert.That(s.BonusScore,Is.EqualTo(500));for(int i=0;i<20;i++)s.CollectCoin();Assert.That(s.BonusScore,Is.EqualTo(500));}
        [Test] public void CloseCallStickerRewardIsGrantedOnlyOnce(){var s=Run();for(int i=0;i<8;i++)s.RegisterNearMiss();int b=s.BonusScore;Assert.That(s.Badges&2,Is.EqualTo(2));s.RegisterNearMiss();Assert.That(s.BonusScore,Is.EqualTo(b+500));}
        [Test] public void DistanceStickerIsReachableAndAwardedOnce(){var s=Run();for(int i=0;i<800;i++){if(i%50==0)s.CollectFuel();s.Tick(.1f);}Assert.That(s.Badges&4,Is.EqualTo(4));Assert.That(s.BonusScore,Is.EqualTo(500));s.Tick(1);Assert.That(s.BonusScore,Is.EqualTo(500));}
        [Test] public void RestartClearsAllExtraRunState(){var s=Run();s.RegisterNearMiss();s.SetBoostHeld(true);s.Tick(1);s.Start();Assert.That(s.Nitro,Is.EqualTo(100));Assert.That(s.NearMisses,Is.EqualTo(0));Assert.That(s.BonusScore,Is.EqualTo(0));Assert.That(s.Badges,Is.EqualTo(0));Assert.That(s.BestCombo,Is.EqualTo(0));Assert.That(s.Boosting,Is.False);}
        [Test] public void NitroTuningRejectsInvalidValues(){Assert.Throws<ArgumentException>(()=>new RunSession(new RunRules{NitroDrainPerSecond=0}));Assert.Throws<ArgumentException>(()=>new RunSession(new RunRules{NitroMultiplier=.5f}));}
        [Test] public void EveryArtPartHasKnownMaterialAndPositiveDimensions(){var names=new System.Collections.Generic.HashSet<string>();foreach(var m in ArtRecipe.Materials())names.Add(m.name);var groups=new[]{ArtRecipe.Car(0,true),ArtRecipe.Car(1,false),ArtRecipe.Car(2,false),ArtRecipe.Road(0),ArtRecipe.Road(5),ArtRecipe.Backdrop(),ArtRecipe.FerrisWheel()};foreach(var parts in groups)foreach(var part in parts){Assert.That(names.Contains(part.material),Is.True,part.material);Assert.That(part.scale.x,Is.GreaterThan(0));Assert.That(part.scale.y,Is.GreaterThan(0));Assert.That(part.scale.z,Is.GreaterThan(0));}}
        [Test] public void RoadPaintContainsExactlyTwoLaneDividers(){var parts=ArtRecipe.Road(0);int markings=0;foreach(var p in parts)if(p.material=="Cream"&&Math.Abs(p.position.y-.025f)<.001f){Assert.That(Math.Abs(p.position.x),Is.EqualTo(1.6f));markings++;}Assert.That(markings,Is.EqualTo(16));}
        [Test] public void AllThreeCameraViewsKeepCarInFrontOfCamera(){for(int mode=0;mode<3;mode++){var p=ArtRecipe.CameraPosition(mode);Assert.That(p.z,Is.LessThan(-8));Assert.That(p.y,Is.GreaterThan(4));Assert.That(ArtRecipe.CameraLook().z,Is.GreaterThan(0));}}
        [Test] public void ToyCarContainsDuckAndFourWheels(){var parts=ArtRecipe.Car(0,true);int tires=0,duck=0;foreach(var p in parts){if(p.material=="Tire"&&p.shape=="Cylinder")tires++;if(p.material=="Lemon"&&p.position.y>1.8f)duck++;}Assert.That(tires,Is.EqualTo(4));Assert.That(duck,Is.GreaterThanOrEqualTo(3));}
    }
}
